  const normalize = value => value.replace(/\s+/g, ' ').trim();
  const englishLookup = new Map();
  const localizedLookup = Object.fromEntries(localeOrder.map(locale => [locale, new Map()]));
  const templateLookup = [];

  function compileTemplate(template) {
    const placeholders = [];
    const pattern = /\{(\w+)\}/g;
    let cursor = 0;
    let source = '^';
    let match;

    while ((match = pattern.exec(template))) {
      source += template.slice(cursor, match.index).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      source += '(.+?)';
      placeholders.push(match[1]);
      cursor = match.index + match[0].length;
    }

    if (!placeholders.length) return null;
    source += template.slice(cursor).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return { regex: new RegExp(`${source}$`), placeholders };
  }

  function indexCatalog(value, path = []) {
    Object.entries(value).forEach(([key, child]) => {
      const nextPath = [...path, key];
      if (Array.isArray(child)) {
        const entry = { path: nextPath, values: child };
        englishLookup.set(normalize(child[0]), entry);
        child.forEach((phrase, index) => {
          if (phrase) localizedLookup[localeOrder[index]].set(normalize(phrase), entry);
        });
        if (child.some(phrase => /\{\w+\}/.test(phrase))) {
          templateLookup.push({ entry, patterns: child.map(compileTemplate) });
        }
      } else {
        indexCatalog(child, nextPath);
      }
    });
  }

